using System;using System.Reflection;using System.Windows.Forms;
class CgContinueChecks{[STAThread]static void Main(){using(var c=new OpeningCgCanvas("","","")){int count=0;c.Completed=()=>count++;var flags=BindingFlags.Instance|BindingFlags.NonPublic;Action click=()=>typeof(OpeningCgCanvas).GetMethod("OnMouseUp",flags).Invoke(c,new object[]{new MouseEventArgs(MouseButtons.Left,1,20,20,0)});click();if(count!=0)throw new Exception("early click skipped CG");typeof(OpeningCgCanvas).GetMethod("PlaybackEnded",flags).Invoke(c,null);if(!c.AwaitingContinue||count!=0)throw new Exception("CG advanced automatically");click();click();if(c.AwaitingContinue||count!=1)throw new Exception("continue must happen once");}using(var c=new OpeningCgCanvas("","","")){int count=0;c.Completed=()=>count++;var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(OpeningCgCanvas).GetMethod("PlaybackEnded",flags).Invoke(c,null);typeof(OpeningCgCanvas).GetMethod("OnKeyDown",flags).Invoke(c,new object[]{new KeyEventArgs(Keys.Enter)});if(count!=1)throw new Exception("keyboard continue failed");}Console.WriteLine("PASS waits after CG, ignores early clicks, continues once and supports Enter");}}
